import{_ as e,o as a,c as i,ai as n}from"./chunks/framework.Duywnu3E.js";const g=JSON.parse('{"title":"Памятка: Настройка сети и траблшутинг","description":"","frontmatter":{},"headers":[],"relativePath":"other/internet_guide.md","filePath":"other/internet_guide.md"}'),l={name:"other/internet_guide.md"};function t(p,s,r,d,h,c){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="памятка-настроика-сети-и-траблшутинг" tabindex="-1">Памятка: Настройка сети и траблшутинг <a class="header-anchor" href="#памятка-настроика-сети-и-траблшутинг" aria-label="Permalink to “Памятка: Настройка сети и траблшутинг”">​</a></h1><p>Краткое руководство по базовой настройке сетевых интерфейсов в <code>etcnet</code> и решению частых проблем.</p><h2 id="траблшутинг-решение-проблем" tabindex="-1">Траблшутинг (решение проблем) <a class="header-anchor" href="#траблшутинг-решение-проблем" aria-label="Permalink to “Траблшутинг (решение проблем)”">​</a></h2><p>Для диагностики сетевой связности используйте утилиту <code>ping</code>.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Проверка связи с конкретным IP-адресом</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.100.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Проверка связи по доменному имени</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ya.ru</span></span></code></pre></div><p>Посмотреть текущие настройки интерфейсов и выданные IP-адреса можно с помощью команды <code>ip a</code> (или <code>ip -c a</code> для цветного вывода).</p><div class="warning custom-block"><p class="custom-block-title">Важно</p><p>После каждого изменения конфигурационных файлов в <code>/etc/net/ifaces/</code> необходимо перезапускать сетевую службу:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span></span></code></pre></div><p>Если служба не перезапускается или выдаёт ошибку, проверьте логи:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span></span></code></pre></div></div><h3 id="типичные-проблемы-и-их-решения" tabindex="-1">Типичные проблемы и их решения: <a class="header-anchor" href="#типичные-проблемы-и-их-решения" aria-label="Permalink to “Типичные проблемы и их решения:”">​</a></h3><ol><li><p><strong>Пингуется IP-адрес в интернете (например, <code>1.1.1.1</code> или <code>8.8.8.8</code>), но не пингуется доменное имя (<code>ya.ru</code>).</strong></p><ul><li><strong>Решение:</strong> Проверьте настройки DNS-сервера. Скорее всего, отсутствует или неверно настроен файл <code>resolv.conf</code> для вашего сетевого интерфейса. Убедитесь, что там указан рабочий DNS-сервер, например, <code>nameserver 8.8.8.8</code>.</li></ul></li><li><p><strong>Не пингуется даже внешний IP-адрес (например, <code>8.8.8.8</code>).</strong></p><ul><li><strong>Решение:</strong> Проверьте, пингуется ли шлюз по умолчанию, указанный в файле <code>ipv4route</code>. Возможно, вы ошиблись в адресе шлюза или забыли его указать.</li></ul></li><li><p><strong>Пингуется шлюз, но нет доступа в интернет.</strong></p><ul><li><strong>Решение:</strong> Скорее всего, на маршрутизаторе (шлюзе) не настроена трансляция адресов (NAT/Masquerade) или отключён форвардинг пакетов (<code>net.ipv4.ip_forward = 1</code>). Подробнее о настройке NAT можно прочитать в <a href="/sa-demo-wiki/module1/task1-2.html">Задании 2</a>.</li></ul></li></ol><h2 id="создание-и-настроика-интерфеисов" tabindex="-1">Создание и настройка интерфейсов <a class="header-anchor" href="#создание-и-настроика-интерфеисов" aria-label="Permalink to “Создание и настройка интерфейсов”">​</a></h2><p>Все сетевые интерфейсы в ALT Linux управляются через подсистему <code>etcnet</code>. Конфигурация каждого интерфейса хранится в отдельной директории по пути <code>/etc/net/ifaces/</code>.</p><p>В рамках стенда у вас будет следующая конфигурация интерфейсов:</p><ul><li><strong>ISP:</strong> 3 интерфейса (<code>ens18</code>, <code>ens19</code>, <code>ens20</code>)</li><li><strong>HQ-RTR и BR-RTR:</strong> 2 интерфейса (<code>ens18</code>, <code>ens19</code>)</li><li><strong>HQ-SRV, HQ-CLI и BR-SRV:</strong> 1 интерфейс (<code>ens18</code>)</li></ul><p>Чтобы создать конфигурацию для нового интерфейса, можно скопировать существующую директорию или создать её вручную:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/net/ifaces/ens18</span></span></code></pre></div><h3 id="настроика-динамического-dhcp-адреса" tabindex="-1">Настройка динамического (DHCP) адреса <a class="header-anchor" href="#настроика-динамического-dhcp-адреса" aria-label="Permalink to “Настройка динамического (DHCP) адреса”">​</a></h3><p>Таким способом настраивается только <code>ens18</code> (интерфейс в сторону интернета) на маршрутизаторе ISP.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ISP</span></span>
<span class="line"><span># /etc/net/ifaces/ens18/options</span></span>
<span class="line highlighted"><span>BOOTPROTO=dhcp</span></span>
<span class="line highlighted"><span>TYPE=eth</span></span>
<span class="line highlighted"><span>CONFIG_IPV4=yes</span></span>
<span class="line highlighted"><span>CONFIG_WIRELESS=no</span></span>
<span class="line highlighted"><span>DISABLED=no</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Другие файлы (<code>ipv4address</code>, <code>ipv4route</code>) для DHCP-интерфейса создавать не нужно — все параметры будут получены от сервера провайдера.</p><h3 id="настроика-статического-адреса" tabindex="-1">Настройка статического адреса <a class="header-anchor" href="#настроика-статического-адреса" aria-label="Permalink to “Настройка статического адреса”">​</a></h3><p>Этим способом настраиваются все остальные интерфейсы в нашей топологии. При необходимости создайте нужные файлы: <code>options</code>, <code>ipv4address</code>, <code>ipv4route</code>, <code>resolv.conf</code>.</p><p><strong>1. Основные параметры (options)</strong></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/net/ifaces/ens18/options</span></span>
<span class="line"><span>BOOTPROTO=static</span></span>
<span class="line highlighted"><span>TYPE=eth</span></span>
<span class="line highlighted"><span>CONFIG_IPV4=yes</span></span>
<span class="line highlighted"><span>CONFIG_WIRELESS=no</span></span>
<span class="line highlighted"><span>DISABLED=no</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>2. IP-адрес и маска (ipv4address)</strong></p><p>В этом файле указывается IP-адрес интерфейса вместе с префиксом маски подсети (в формате CIDR).</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/net/ifaces/ens18/ipv4address</span></span>
<span class="line highlighted"><span>172.16.1.1/28</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>3. Шлюз по умолчанию (ipv4route)</strong></p><p>Здесь указывается IP-адрес маршрутизатора, через который будет идти трафик в другие сети.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/net/ifaces/ens18/ipv4route</span></span>
<span class="line highlighted"><span>default via 172.16.1.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>4. DNS-сервер (resolv.conf)</strong></p><p>Адрес сервера для разрешения доменных имён. Можно указать публичные серверы (Google, Яндекс) или свой локальный DNS.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/net/ifaces/ens18/resolv.conf</span></span>
<span class="line highlighted"><span>nameserver 8.8.8.8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Если вы хотите указать несколько DNS-серверов, просто добавьте дополнительные строки <code>nameserver &lt;IP&gt;</code> каждую с новой строки.</p></div>`,33)])])}const k=e(l,[["render",t]]);export{g as __pageData,k as default};
